<?php
declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/config/config.php';require_once $root.'/includes/services/PlanetService.php';
$pdo=db();$player=(int)$pdo->query('SELECT player_id FROM player_colonies ORDER BY id LIMIT 1')->fetchColumn();if($player<1){fwrite(STDERR,"planet_fixture_missing\n");exit(2);} $planet=(int)$pdo->query('SELECT id FROM universe_planets WHERE is_colonizable=1 AND is_occupied=0 AND habitability>=0.25 ORDER BY id LIMIT 1')->fetchColumn();if($planet<1){fwrite(STDERR,"free_planet_missing\n");exit(2);} $service=new PlanetService($pdo);$snapshot=$service->list($player);$checks=['snapshot_state'=>in_array($snapshot['state'],['ready','empty'],true),'formula_present'=>str_contains($snapshot['formula'],'biome')];if($snapshot['state']==='ready'){$row=$snapshot['colonies'][0];$checks['output_calculated']=(int)$row['production_output']>0&&isset($row['life_support_state'],$row['food_ratio'],$row['water_ratio']);$checks['owned_scope']=(int)$row['player_id']===$player;}$resource=$pdo->prepare('SELECT naquadah FROM player_resources WHERE player_id=?');$resource->execute([$player]);$before=(int)$resource->fetchColumn();$explore=$service->explore($player,'Contract Frontier','anomaly');$resource->execute([$player]);$afterExplore=(int)$resource->fetchColumn();$checks['exploration_success']=($explore['state']??'')==='success'&&$afterExplore===$before-25000;$colonyName='Contract Colony '.substr(str_replace('.','',uniqid('',true)),-8);$colonize=$service->colonize($player,$planet,$colonyName);$checks['colonize_success']=($colonize['state']??'')==='success'&&$colonize['planet_id']===$planet;$resource->execute([$player]);$afterColonize=(int)$resource->fetchColumn();$checks['colonization_cost']=$afterColonize===$before-75000;$listAfter=$service->list($player);$checks['new_colony_visible']=count(array_filter($listAfter['colonies'],static fn(array $c):bool=>(int)$c['planet_id']===$planet))===1;$exploreId=(int)$explore['exploration_id'];$colonyId=(int)$colonize['colony_id'];$pdo->prepare('DELETE FROM player_colonies WHERE id=?')->execute([$colonyId]);$pdo->prepare('UPDATE universe_planets SET is_occupied=0 WHERE id=?')->execute([$planet]);$pdo->prepare('UPDATE player_resources SET naquadah=naquadah+75000 WHERE player_id=?')->execute([$player]);$pdo->prepare('DELETE FROM planet_explorations WHERE id=?')->execute([$exploreId]);$pdo->prepare("DELETE FROM game_events WHERE entity_type='planet' AND entity_id IN (?,?)")->execute([$exploreId,$colonyId]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key IN ('planet_explore','planet_colonize')")->execute([$player]);$failures=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));echo json_encode(['status'=>$failures?'failed':'passed','checks'=>$checks,'failures'=>$failures,'exploration'=>$explore,'colonization'=>$colonize],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failures?1:0);
